// Cyclic Noise (Ray Marching)
// Inspired by "Cyclic noise 2D" by nimitz (@stormoid) - https://www.shadertoy.com/view/fcjXzh (MIT)
// Brings the core of cyclic noise into 3D and uses it to COLOR the ray-marched
// surface: assigns textureCol starting from the hit point pModel.
//
// Engine variables available in this block (Ray Marching tab):
//   pModel       = hit point on the surface (vec3, model space)
//   n_model      = surface normal at the hit point (vec3)
//   textureCol   = color to assign (already initialized to ubuf.color)
//   ubuf.u_time  = animated time; ubuf.u_col1 / ubuf.u_col2 = dock colors
// NB: no mainImage, no return, no gl_FragCoord in this tab.

// --- Cyclic noise 3D: iterated loop of |dot(cos,sin)| with distortion and rotation ---
float result = 0.0;
float z = 0.95;
float distort = 2.1;
float dstAmount = 0.10;
float wsum = 0.0;

// rotation matrix (the 2D original used a mat2 ~13deg *1.5)
mat3 m2 = mat3(
    0.97367,  0.22798, 0.0,
   -0.22798,  0.97367, 0.0,
    0.0,      0.0,     1.0) * 1.5;

// coordinates: the point on the surface + slight temporal scroll.
// SCALE: raise this value for denser clouds/filaments (2.3 = wide, 3.2 = dense).
vec3 p = pModel * 3.2 + vec3(0.0, 0.0, ubuf.u_time * 0.05);

for (int i = 0; i < 8; i++) {
    p += sin(p.yzx * distort + ubuf.u_time * 0.27 * pow(distort, 1.35)) * dstAmount;
    result += abs(dot(cos(p), sin(p.zxy)) * z);
    wsum   += z;
    z       *= 0.65;
    distort *= 1.35;
    p        = m2 * p;
}
float ncyc = result / wsum;   // ~[0,1]

// noise contrast: tighten these two ends for denser/fuller ridges
// (0.15,0.75 = soft; 0.28,0.60 = denser). Widen them for more 'holes'.
float mixT = smoothstep(0.28, 0.60, ncyc);

// DOCK COLORS: u_col2 in the valleys, u_col1 on the flow ridges.
// The mix is driven by the scalar noise so the two dock colors
// (ubuf.u_col1 / ubuf.u_col2) stay recognizable.
vec3 cyclicCol = mix(ubuf.u_col2, ubuf.u_col1, mixT);

// veining: slight banded modulation (phase-shifted sin) toward the ridge color,
// without introducing hues foreign to the two dock colors.
float bands = dot(sin(vec3(1.15, 1.65, 2.25) * ncyc * 6.2 + 4.2) * 0.5 + 0.5, vec3(0.333));
cyclicCol = mix(cyclicCol, ubuf.u_col1, bands * 0.15);

// edge sheen (fresnel) from the normal: lights the ridges on color u_col1
float fres = pow(1.0 - abs(n_model.z), 2.0);
cyclicCol += ubuf.u_col1 * fres * 0.25 * ncyc;

textureCol = cyclicCol;
